const e="canada",l=1,s={habitants:"les Canadiens",adjectif:"canadien",adjectifF:"canadienne",devise:"Poliment, mais fermement : tout le monde s’excuse, personne ne vote la même chose.",medaillon:"CA",chaineInfo:"CA NOUVELLES",hymne:"Ô Canada, terre de nos aïeux et de nos négociations provinciales"},a={chambre:"Chambre des communes",chambreLong:"Chambre des communes du Canada",chefGouvernement:"Premier ministre",chefEtat:"Gouverneur général (au nom du Souverain, rôle protocolaire)",passageForce:{label:"Motion de clôture",description:"Le gouvernement limite la durée du débat et force le vote. L’opposition dénonce une atteinte à la démocratie, tout en préparant sa propre motion de clôture pour quand elle sera au pouvoir.",news:"Motion de clôture : « {loi} » est mis aux voix sous les huées polies"},censure:{label:"Vote de défiance",description:"Si le gouvernement perd un vote de confiance à la Chambre, il doit démissionner ou demander des élections. La perte d’un seul vote peut tout faire basculer, d’où la présence de tous les députés, même malades.",news:"Vote de défiance : la Chambre menace de renverser le gouvernement"},dissolution:{label:"Dissolution et élections fédérales",description:"Le Premier ministre demande à la gouverneure générale de dissoudre la Chambre. Ottawa part en campagne en plein hiver, avec des bottes et des promesses en deux langues.",news:"Dissolution : le Canada retourne aux urnes, manteau boutonné jusqu’au col"}},n={type:"federales",label:"Élections fédérales",intro:"Trente-trois jours de campagne pour parcourir un pays plus vaste que l’Europe. Les chefs de parti font le tour des Maritimes, du Québec, de l’Ontario, des Prairies et de la Colombie-Britannique en autobus, avec un arrêt obligatoire au café de beignets.",adversaires:[{id:"thomas-delorme",name:"Thomas Delorme",parti:"Parti Conservateur du Dominion",style:"attaque",punchlines:["Le gouvernement augmente les taxes et baisse le moral des ménages, ce qui est une performance rare.","Mon adversaire est poli, ce qui n’est pas encore une politique économique.","Un pays aussi grand mérite un chef qui connaît au moins la moitié de ses provinces."],genre:"m"},{id:"genevieve-landry",name:"Geneviève Landry",parti:"Nouveau Parti du Peuple",style:"emotion",punchlines:["Dans chaque province, des familles attendent un logement, un médecin, une garderie. Pas un rapport.","On ne mesure pas un pays à son PIB mais à la longueur de sa liste d’attente.","Je vous rappelle que la santé, ce sont des gens, pas des tableaux croisés dynamiques."],genre:"f"},{id:"jean-marc-thibault",name:"Jean-Marc Thibault",parti:"Bloc des Intérêts du Québec",style:"chiffres",punchlines:["Je défends les intérêts du Québec à Ottawa : 32 sièges, et autant de nuances.","Chaque dollar du Québec revient en transferts, quand il revient.","Vous voulez du fédéralisme d’ouverture ? Commencez par ouvrir un dossier."]}],nuitElectorale:"Les résultats arrivent de l’Atlantique vers le Pacifique, et la soirée se transforme en suspense géographique : on attend la Colombie-Britannique, qui vote encore pendant que les Maritimes dorment."},t=[{id:"canada-assurance-medicaments",title:"Régime national d’assurance médicaments",domain:"sante",description:"Un seul régime pour les médicaments, négocié avec dix provinces et trois territoires. Le texte est prêt, il ne manque que treize signatures et quelques virgules.",accroche:"Les pilules seront couvertes, sauf la pilule de la négociation avec les provinces.",effects:{cohesion:3,pouvoirAchat:2,budget:-6,assemblee:-1},delayed:[{delay:3,effects:{cohesion:1,popularite:1},label:"Ordonnances moins coûteuses"}],groupStance:{"liberaux-canada":.7,"conservateurs-canada":-.5,"bloc-quebec":-.2,"nouveau-democrate":.9,"verts-canada":.5,"populaires-ouest":-.9},streetAnger:.3},{id:"canada-tarification-carbone-federale",title:"Prix fédéral du carbone avec ristourne",domain:"ecologie",description:"Taxer le carbone puis rendre l’argent aux ménages. Beaucoup n’ont pas compris la deuxième partie, ce qui est le principal défaut d’une idée pourtant simple.",accroche:"Le carbone paie, et la ristourne arrive, en même temps que le prochain dégel.",effects:{ecologie:4,budget:1,popularite:-4,pouvoirAchat:-2},delayed:[{delay:3,effects:{ecologie:1,pouvoirAchat:1},label:"Ristournes versées, enfin remarquées"},{delay:4,effects:{popularite:-1},label:"Campagne « supprimons la taxe »"}],groupStance:{"liberaux-canada":.6,"conservateurs-canada":-1,"bloc-quebec":-.3,"nouveau-democrate":.4,"verts-canada":.9,"populaires-ouest":-1},streetAnger:.6},{id:"canada-ententes-provinces-sante",title:"Transferts en santé conditionnés aux résultats",domain:"sante",description:"Verser aux provinces des milliards contre des cibles de réduction des attentes aux urgences. Chaque première ministre provinciale rappelle la compétence exclusive des provinces, puis tend la main.",accroche:"On verse les fonds contre des résultats, et on cherche d'abord comment les mesurer.",effects:{cohesion:2,budget:-6,assemblee:1,popularite:1},delayed:[{delay:4,effects:{cohesion:1,popularite:1},label:"Délais d’attente en recul sur le papier"}],groupStance:{"liberaux-canada":.5,"conservateurs-canada":.2,"bloc-quebec":.6,"nouveau-democrate":.5,"verts-canada":.3,"populaires-ouest":-.4},streetAnger:.2},{id:"canada-oleoduc-cote-ouest",title:"Corridor énergétique vers la côte Pacifique",domain:"energie",description:"Un nouveau corridor pour acheminer le pétrole de l’Ouest vers l’Asie. Les communautés autochtones, les municipalités côtières et les saumons ont déjà exprimé trois réserves distinctes.",accroche:"Un tuyau jusqu'au Pacifique, avec une étape de consultation tous les cent mètres.",effects:{economie:4,budget:1,ecologie:-6,cohesion:-3},delayed:[{delay:3,effects:{economie:1,budget:1},label:"Redevances et emplois"},{delay:4,effects:{ecologie:-2,cohesion:-2},label:"Recours devant les tribunaux"}],groupStance:{"liberaux-canada":.1,"conservateurs-canada":.9,"bloc-quebec":-.6,"nouveau-democrate":-.7,"verts-canada":-1,"populaires-ouest":.7},streetAnger:.6},{id:"canada-quotas-immigration-econ",title:"Cibles pluriannuelles d’immigration économique",domain:"securite",description:"Accueillir davantage de travailleurs qualifiés en pénurie, dans les régions qui les attendent. Les infirmières arrivent, les logements un peu moins vite.",accroche:"Les nouveaux arrivants sont accueillis chaleureusement, malgré les moins vingt dehors.",effects:{economie:3,cohesion:-2,pouvoirAchat:-1,popularite:-1},delayed:[{delay:4,effects:{economie:2,budget:1},label:"Pénuries de main-d’œuvre atténuées"}],groupStance:{"liberaux-canada":.6,"conservateurs-canada":.2,"bloc-quebec":-.4,"nouveau-democrate":.3,"verts-canada":.4,"populaires-ouest":-.6},streetAnger:.3},{id:"canada-logement-abordable",title:"Stratégie nationale du logement",domain:"logement",description:"Financer 300 000 logements abordables avec les provinces, les villes et les promoteurs. Chaque palier se félicite d’en avoir eu l’idée en premier.",accroche:"Un toit pour tous, y compris pour la pelle à neige, qui en demande deux.",effects:{pouvoirAchat:3,cohesion:2,budget:-6,economie:1},delayed:[{delay:3,effects:{pouvoirAchat:1,cohesion:1},label:"Premières livraisons de logements"},{delay:4,effects:{popularite:1},label:"Inaugurations de chantiers"}],groupStance:{"liberaux-canada":.6,"conservateurs-canada":-.2,"bloc-quebec":.4,"nouveau-democrate":.8,"verts-canada":.5,"populaires-ouest":-.7},streetAnger:.3},{id:"canada-langues-officielles-modern",title:"Modernisation de la loi sur les langues officielles",domain:"institutions",description:"Mettre à jour le bilinguisme, avec un chapitre sur le français hors Québec et un autre sur les formulaires qui parlent trop anglais. Un consensus de fortune s’y dessine.",accroche:"Deux langues officielles, un seul panneau, et une paire de lunettes pour tout lire.",effects:{cohesion:2,popularite:1,assemblee:1,budget:-2},delayed:[{delay:3,effects:{cohesion:1},label:"Services fédéraux plus accessibles"}],groupStance:{"liberaux-canada":.7,"conservateurs-canada":-.2,"bloc-quebec":.8,"nouveau-democrate":.4,"verts-canada":.2,"populaires-ouest":-.9},streetAnger:.1},{id:"canada-defense-arctique",title:"Plan de défense et de souveraineté arctique",domain:"securite",description:"Des brise-glaces, des radars et des bases pour surveiller un territoire où il y a plus d’ours polaires que de contribuables. La souveraineté se mesure en kilomètres de glace.",accroche:"Nous défendrons le Grand Nord, d'abord contre le gel, ensuite contre les rumeurs.",effects:{securite:4,international:2,budget:-6,popularite:-1},delayed:[{delay:4,effects:{securite:1,international:1},label:"Présence arctique renforcée"}],groupStance:{"liberaux-canada":.4,"conservateurs-canada":.8,"bloc-quebec":-.5,"nouveau-democrate":-.3,"verts-canada":-.5,"populaires-ouest":.3},streetAnger:.1},{id:"canada-secteur-forestier-resilience",title:"Fonds de résilience forestière",domain:"ecologie",description:"Financer l’aménagement des forêts contre les incendies, avec des coupe-feu, des équipes et un nombre réduit de rapports sur le sujet. Les chiffres restent graves, mais plus lisibles.",accroche:"Les forêts résistent, les scieries aussi, et la hache demande poliment pardon.",effects:{ecologie:2,securite:1,budget:-4,economie:1},delayed:[{delay:3,effects:{ecologie:1,securite:1},label:"Moins de superficie brûlée"}],groupStance:{"liberaux-canada":.6,"conservateurs-canada":.2,"bloc-quebec":.3,"nouveau-democrate":.7,"verts-canada":.8,"populaires-ouest":-.4},streetAnger:.1},{id:"canada-travailleurs-garde-enfants",title:"Garderies à tarif réduit à l’échelle du pays",domain:"travail",description:"Des places en garderie à dix dollars par jour, si l’on trouve une place. Le prix est national, la liste d’attente aussi.",accroche:"Des garderies à prix doux, avec liste d'attente prévue pour la génération d'après.",effects:{pouvoirAchat:3,cohesion:2,budget:-6,economie:1},delayed:[{delay:3,effects:{economie:1,pouvoirAchat:1},label:"Plus de parents au travail"}],groupStance:{"liberaux-canada":.8,"conservateurs-canada":-.4,"bloc-quebec":.6,"nouveau-democrate":.9,"verts-canada":.4,"populaires-ouest":-.8},streetAnger:.1}],i=[{id:"canada-feux-de-foret",title:"Feux de forêt dans l’Ouest",category:"climat",description:"Des feux de forêt gigantesques forcent des évacuations, couvrent de fumée des villes entières à deux mille kilomètres et rendent un ciel orange que même les satellites commentent. Les provinces demandent des moyens fédéraux.",weight:7,minTurn:3,choices:[{id:"forces-armees",label:"Déployer les Forces armées canadiennes",description:"Évacuer, ravitailler, éteindre.",effects:{securite:2,cohesion:2,budget:-5,popularite:1},delayed:[{delay:3,effects:{cohesion:1},label:"Reconnaissance des communautés évacuées"}],news:"Feux de forêt : l’armée à pied d’œuvre, la fumée aussi"},{id:"aide-provinces",label:"Débloquer un fonds d’urgence pour les provinces",description:"Plus d’argent, moins de commandement.",effects:{cohesion:1,budget:-6,assemblee:1},news:"Fonds d’urgence : Ottawa paie, les provinces commandent"},{id:"negocier",label:"Réunir un sommet sur la gestion des feux",description:"Convoquer premiers ministres et experts avec carte et café.",effects:{popularite:-3,cohesion:-1,ecologie:1,budget:-1},delayed:[{delay:3,effects:{ecologie:1,cohesion:1},label:"Feuille de route commune"}],news:"Sommet sur les feux : on discute, les forêts brûlent"}]},{id:"canada-tensions-provinciales",title:"Querelle entre Ottawa et une province",category:"politique",description:"Une première ministre provinciale menace de se retirer d’un programme fédéral, puis de contester la Constitution, puis de revenir à la table. Chaque étape comporte un communiqué de presse en deux langues.",weight:6,minTurn:3,choices:[{id:"compromis",label:"Offrir une entente asymétrique",description:"Accorder plus de pouvoirs à une province, et inévitablement aux autres.",effects:{cohesion:2,assemblee:1,budget:-3,popularite:-1},delayed:[{delay:3,effects:{assemblee:-2},label:"Les autres provinces réclament la même chose"}],news:"Entente asymétrique : tout le monde est content, sauf neuf provinces"},{id:"tribunaux",label:"Aller en Cour suprême",description:"Laisser les juges trancher à la place des élus.",effects:{popularite:-2,cohesion:-3,assemblee:-2,international:1},delayed:[{delay:4,effects:{cohesion:1},label:"Jugement partiellement favorable"}],news:"Ottawa et la province s’affrontent devant la Cour suprême"},{id:"tournee",label:"Faire une tournée de réconciliation",description:"Un déplacement dans chaque capitale provinciale, avec cadeaux locaux.",effects:{popularite:1,cohesion:1,budget:-2},delayed:[{delay:2,effects:{popularite:-2},label:"Promesses sans suite"}],news:"Tournée des capitales : le PM goûte quatre sirops d’érable"}]},{id:"canada-hiver-tempete-verglas",title:"Verglas et grand froid",category:"climat",description:"Une tempête de verglas coupe le courant pendant plusieurs jours. Les lignes pendent comme des guirlandes de Noël, les poêles à bois remontent en cote et tout le monde se rappelle l’existence du mot « polaire ».",weight:6,minTurn:3,choices:[{id:"aide-reseau",label:"Envoyer des renforts aux équipes de réseau",description:"Plus de camions, plus d’électriciens, moins de conférences.",effects:{cohesion:2,budget:-5,popularite:1,securite:1},delayed:[{delay:3,effects:{economie:1},label:"Réseau rétabli"}],news:"Verglas : les camions-nacelles débarquent en rangs serrés"},{id:"abris",label:"Ouvrir des centres de chaleur",description:"Gymnases, salles paroissiales et soupe chaude.",effects:{cohesion:3,budget:-3,popularite:1},news:"Des gymnases transformés en refuges, la soupe est déclarée essentielle"},{id:"minimum",label:"Laisser la province gérer",description:"Rappeler que le réseau électrique est un dossier provincial.",effects:{popularite:-4,cohesion:-3,budget:1},delayed:[{delay:3,effects:{popularite:-1},label:"Colère des sinistrés"}],news:"Verglas : Ottawa « suit la situation », en manteau"}]},{id:"canada-blocage-pont-frontalier",title:"Blocage commercial à la frontière",category:"economie",description:"Des camionneurs bloquent un pont commercial avec le voisin du sud. Les usines d’automobiles s’arrêtent, les cafés alentour battent des records de recettes.",weight:5,minTurn:4,conditions:[{gauge:"economie",op:"<",value:62}],choices:[{id:"injonction",label:"Obtenir une injonction et déblayer",description:"Rétablir la circulation sans état d’urgence.",effects:{economie:2,securite:1,popularite:-2,cohesion:-2},news:"Le pont rouvre : les remorqueuses font la file"},{id:"negocier-camionneurs",label:"Recevoir une délégation de camionneurs",description:"Parler, boire du café, promettre un comité.",effects:{popularite:1,cohesion:1,economie:-2,budget:-1},delayed:[{delay:3,effects:{economie:1,cohesion:1},label:"Pont rouvert à l’amiable"}],news:"Le PM reçoit les camionneurs, le comité est nommé"},{id:"laisser",label:"Attendre que la neige fasse son travail",description:"Parier sur la fatigue des manifestants.",effects:{economie:-5,international:-3,popularite:-3},news:"Pont fermé : les usines de Windsor chôment, l’exécutif patiente"}]},{id:"canada-referendum-souverainiste",title:"Menace de référendum sur l’autonomie",category:"politique",description:"Un parti provincial annonce un référendum sur plus d’autonomie. La question n’est pas écrite, la réponse non plus, mais l’ambiance est déjà plus chaude que le thermomètre.",weight:4,minTurn:5,choices:[{id:"clarte",label:"Rappeler une règle de clarté",description:"Exiger une question claire et une majorité nette.",effects:{cohesion:1,assemblee:-2,popularite:-1,international:1},delayed:[{delay:3,effects:{cohesion:1},label:"Débat apaisé"}],news:"Ottawa exige la clarté, les juristes sortent leurs lunettes"},{id:"concessions",label:"Proposer des concessions budgétaires",description:"Des transferts plus généreux pour calmer les esprits.",effects:{cohesion:2,budget:-5,popularite:1,assemblee:1},delayed:[{delay:3,effects:{budget:-1},label:"Autres provinces réclament leur part"}],news:"Plus d’argent pour la province, moins de ferveur pour le référendum"},{id:"ignorer",label:"Ne pas réagir",description:"Éviter de donner de l’oxygène à la polémique.",effects:{popularite:-2,cohesion:-3,assemblee:-1},news:"Ottawa « ne commente pas », ce qui est un commentaire"}]},{id:"canada-inondations-printemps",title:"Crues printanières",category:"climat",description:"La fonte des neiges fait déborder les rivières. Les sacs de sable sont empilés, les bénévoles organisent des chaînes humaines et la Garde côtière découvre qu’elle a aussi des lacs.",weight:5,minTurn:3,choices:[{id:"aide-sinistres",label:"Débloquer un programme d’aide aux sinistrés",description:"Indemniser rapidement pour éviter les files de guichets.",effects:{cohesion:2,budget:-5,popularite:1},delayed:[{delay:3,effects:{popularite:1},label:"Reconnaissance locale"}],news:"Crues : l’aide aux sinistrés arrive avant la décrue"},{id:"zone-inondable",label:"Interdire de reconstruire en zone inondable",description:"Une mesure impopulaire, mais utile.",effects:{ecologie:2,cohesion:-3,popularite:-3,budget:1},delayed:[{delay:4,effects:{ecologie:1,budget:1},label:"Moins de dégâts futurs"}],news:"Zones inondables : reconstruction interdite, riverains furieux"},{id:"assurance",label:"Créer un régime d’assurance catastrophe",description:"Partager le risque avec les assureurs, qui déclarent apprécier la nuance.",effects:{economie:1,budget:-3,cohesion:1,popularite:1},news:"Régime d’assurance catastrophe : un paquet de formulaires de plus"}]},{id:"canada-epicerie-nord",title:"Pénurie dans les épiceries du Nord",category:"economie",description:"Les communautés nordiques paient les produits frais au prix du caviar. Un panier d’épicerie familial dépasse le salaire d’une semaine. La question arrive à la Chambre sous forme de chou-fleur.",weight:4,minTurn:4,choices:[{id:"subvention",label:"Étendre le programme Nutrition Nord",description:"Subventionner les denrées de base.",effects:{pouvoirAchat:2,cohesion:2,budget:-5},news:"Nutrition Nord élargi : le chou-fleur baisse enfin de prix"},{id:"transport",label:"Financer des routes et des vols supplémentaires",description:"Une solution à moyen terme.",effects:{economie:1,cohesion:1,budget:-6,popularite:1},delayed:[{delay:4,effects:{pouvoirAchat:1},label:"Prix en baisse"}],news:"Routes d’hiver : le Nord se rapproche d’Ottawa de quelques heures"},{id:"rapport",label:"Commander un rapport",description:"Un chef-d’œuvre de la littérature administrative.",effects:{popularite:-2,cohesion:-2,budget:-1},news:"Pénurie dans le Nord : un rapport est « en cours de préparation »"}]}],r=[{id:"canada-confiance-chambre",title:"Survivre à un vote de confiance",brief:"Ne laisser aucune jauge dans le rouge : un vote de confiance se perd pour moins que ça, et il se gagne rarement avec le sourire.",objective:{type:"noRedGauge"},reward:{assemblee:2,popularite:1},news:"Vote de confiance : le gouvernement tient, de justesse et de bon gré"},{id:"canada-logement-abordable-mission",title:"Rendre le logement abordable",brief:"Pouvoir d’achat à 58 : assez pour qu’on cesse de comparer le prix d’un studio à celui d’une province.",objective:{type:"gaugeAtLeast",gauge:"pouvoirAchat",value:58},reward:{pouvoirAchat:2,cohesion:1},news:"Logement : le loyer médian recule d’un café"},{id:"canada-cohesion-federale",title:"Apaiser la fédération",brief:"Gagner quatre points de cohésion sans froisser plus de cinq provinces. Une mission pour diplomates endurants.",objective:{type:"gaugeGain",gauge:"cohesion",value:4},reward:{cohesion:2,assemblee:1},news:"Fédération : un communiqué conjoint, signé en deux langues et sept stylos"},{id:"canada-ecoute-ouest",title:"Faire adopter un texte avec le soutien de l’Ouest",brief:"Un texte voté : l’Ouest, le Québec et les Maritimes ont chacun une conviction, mais un seul vote.",objective:{type:"lawAdopted"},reward:{assemblee:2,popularite:1},news:"Ottawa : un texte adopté, personne ne parle d’aliénation pendant un trimestre"},{id:"canada-visite-d-etat",title:"Recevoir un dirigeant étranger",brief:"Une visite d’État ce trimestre : garde d’honneur, échange de cadeaux et entretien poli, dans les deux langues officielles.",objective:{type:"visitHeld"},reward:{international:2,economie:1},news:"Visite d’État : poignée de main bilingue et communiqué en deux versions",room:"salon",scene3d:"visite"}],o=JSON.parse('{"medias":["La Gazette des Deux Rives","Radio Boréale","Info-Déneigement 24","Le Matin du Nord-Ouest","Le Journal du Comptoir à beignes"],"journalistes":[{"id":"canada-j-gagnon","name":"Mathieu Gagnon-Lavoie","media":"La Gazette des Deux Rives","style":"poli : pose sa question trois fois en s’excusant à chaque fois","genre":"m"},{"id":"canada-j-sandhu","name":"Amrita Sandhu","media":"Radio Boréale","style":"méthodique : chronomètre les réponses et les pauses au dixième de seconde","genre":"f"},{"id":"canada-j-macrae","name":"Colin MacRae","media":"Le Matin du Nord-Ouest","style":"direct : ramène l’oléoduc dans la conversation, même pendant la météo","genre":"m"},{"id":"canada-j-bouchard","name":"Sophie Bouchard-Pelletier","media":"Info-Déneigement 24","style":"tenace : relance jusqu’à ce que le micro gèle","genre":"f"},{"id":"canada-j-tremblay","name":"Gilles Tremblay","media":"Le Journal du Comptoir à beignes","style":"gourmand : relie chaque crise à la pâtisserie du jour","genre":"m"},{"id":"canada-j-okafor","name":"Naomi Okafor","media":"La Gazette des Deux Rives","style":"perspicace : lit les annexes budgétaires pour le plaisir","genre":"f"},{"id":"canada-j-leblanc","name":"Étienne Leblanc","media":"Radio Boréale","style":"nostalgique : compare tout aux hivers d’autrefois","genre":"m"}],"questions":[{"id":"canada-q-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef du gouvernement, votre cote de confiance descend plus vite que le mercure en janvier. Vos conseillers vous cachent-ils les sondages sous la tuque ?","answers":[{"tone":"franche","label":"Je les lis tous, et ils sont frisquets. Je dois mieux expliquer mes choix, et je vais le faire sans me cacher derrière un communiqué.","effects":{"popularite":5,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les députés sentent le vent tourner"}],"news":"Le Premier ministre admet que les sondages sont « frisquets »"},{"tone":"langue-de-bois","label":"Un sondage est une photo de l’instant, et je gouverne pour la durée. Le cap est clair, la méthode est claire, et la clarté est très claire.","effects":{"popularite":2,"assemblee":-2},"news":"Le Premier ministre compare les sondages à une photo d’hiver"},{"tone":"offensive","label":"Ces chiffres sont commandés par des gens qui préfèrent le blocage au progrès. Ma cote est dans les usines et les garderies, pas dans les instituts.","effects":{"popularite":5,"international":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les médias contre-attaquent avec des graphiques"}],"news":"Sondages : le Premier ministre s’en prend aux « marchands de blocage »"}]},{"id":"canada-q-trop-populaire","theme":"popularite","condition":{"gauge":"popularite","op":">","value":65},"text":"Votre popularité est si haute que même l’opposition vous salue poliment dans l’ascenseur. Qu’avez-vous fait de mal pour être aussi aimé ?","answers":[{"tone":"franche","label":"Rien d’exceptionnel : j’ai tenu mes promesses, et j’en ai oublié quelques-unes. La popularité fond vite, je ne m’y installe pas.","effects":{"popularite":3,"assemblee":-2},"news":"Le Premier ministre : « J’ai oublié quelques promesses »"},{"tone":"langue-de-bois","label":"Les Canadiens sont généreux avec ceux qui les écoutent. Je continue d’écouter, et je continue de m’excuser quand j’ai tort.","effects":{"popularite":2,"economie":-2},"news":"Le Premier ministre mise sur l’écoute et les excuses"},{"tone":"offensive","label":"Si l’opposition m’aime autant, qu’elle vote mes budgets. Les politesses en ascenseur ne remplacent pas un vote à la Chambre.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"L’opposition refuse de se faire flatter"}],"news":"Le Premier ministre défie l’opposition : « Votez mes budgets »"}]},{"id":"canada-q-dollar-tarifs","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Les exportateurs menacent de fermer des usines si le voisin du sud relève encore ses droits de douane. Votre stratégie, c’est de souhaiter bonne chance ou d’appeler ?","answers":[{"tone":"franche","label":"J’ai appelé, et je rappellerai. Notre économie dépend de ce voisin, et je préfère un compromis imparfait à une guerre de tarifs parfaite.","effects":{"economie":4,"international":2,"popularite":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les concessions agacent les exportateurs"}],"news":"Tarifs : le Premier ministre préfère le téléphone aux représailles"},{"tone":"langue-de-bois","label":"Nous diversifions nos marchés, nous soutenons nos industries et nous suivons le dossier de près. Les discussions se poursuivent dans un esprit constructif.","effects":{"economie":2,"popularite":-3},"news":"Tarifs : « un esprit constructif », répète le Premier ministre"},{"tone":"offensive","label":"Si on nous tape sur les doigts, on répondra sur l’acier et le bois. Nous sommes polis, pas des paillassons.","effects":{"popularite":5,"economie":3,"international":-5},"delayed":[{"delay":3,"effects":{"economie":-3},"label":"Les prix grimpent des deux côtés de la frontière"},{"delay":4,"effects":{"international":-2},"label":"Le voisin laisse les téléphones sonner"}],"news":"Le Premier ministre : « Polis, pas des paillassons »"}]},{"id":"canada-q-croissance-surplus","theme":"economie","condition":{"gauge":"economie","op":">","value":65},"text":"La croissance est vigoureuse, les chantiers fleurissent, les camions de béton se garent sur les trottoirs. Pourquoi les ménages ne sentent-ils rien dans leur portefeuille ?","answers":[{"tone":"franche","label":"Parce que la croissance est mal répartie, et que le logement avale tout. Je reconnais le problème, et je ne vais pas féliciter les statistiques.","effects":{"popularite":4,"economie":-2},"news":"Le Premier ministre : « La croissance n’arrive pas au portefeuille »"},{"tone":"langue-de-bois","label":"L’économie est solide, les fondamentaux sont sains et la confiance revient graduellement, comme le printemps, plus ou moins.","effects":{"economie":2,"popularite":-2},"news":"Le Premier ministre compare la confiance au printemps"},{"tone":"offensive","label":"Ceux qui ne sentent rien devraient visiter un chantier : on y embauche, et on y mange du bon café. Le pessimisme coûte cher et ne rapporte rien.","effects":{"economie":4,"popularite":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les syndicats demandent la fin du café gratuit"}],"news":"Le Premier ministre invite les sceptiques sur un chantier"}]},{"id":"canada-q-deficit-transferts","theme":"budget","condition":{"gauge":"budget","op":"<","value":40},"text":"Le déficit gonfle, et les provinces réclament plus de transferts pour la santé. Qui va payer ? Vos successeurs, ou la chaîne de montage de photocopieurs ?","answers":[{"tone":"franche","label":"Nous ne pouvons pas tout promettre à tout le monde. Je propose des transferts liés à des résultats, et des compressions ailleurs. Ce sera impopulaire.","effects":{"budget":4,"popularite":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"budget":2},"label":"Les premiers gains de l’efficacité apparaissent"}],"news":"Santé : le Premier ministre lie les transferts aux résultats"},{"tone":"langue-de-bois","label":"Le dialogue avec nos partenaires provinciaux est constant, respectueux et très long. Une rencontre est prévue pour planifier la prochaine rencontre.","effects":{"budget":2,"international":-2},"news":"Le Premier ministre annonce une rencontre pour planifier une rencontre"},{"tone":"offensive","label":"Le déficit vient d’un manque de rigueur dans plusieurs provinces. Qu’elles commencent par nettoyer leurs propres bureaux avant de réclamer des chèques.","effects":{"budget":5,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les premiers ministres provinciaux claquent la porte"}],"news":"Transferts : le Premier ministre renvoie les provinces à leur ménage"}]},{"id":"canada-q-sante-attente","theme":"budget","text":"On attend huit heures à l’urgence, et des millions de gens n’ont pas de médecin de famille. Combien coûte la santé de ce pays, et combien de temps faut-il attendre pour le savoir ?","answers":[{"tone":"franche","label":"Trop, et pour trop peu de résultats. Je veux plus d’infirmières, moins de paperasse, et des comptes clairs à tous les paliers.","effects":{"popularite":4,"budget":-3},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les premières embauches rassurent les urgences"}],"news":"Santé : le Premier ministre promet « plus d’infirmières, moins de papier »"},{"tone":"langue-de-bois","label":"La santé est une compétence partagée, et une collaboration étroite avec les partenaires est la seule voie. Le temps d’attente est un indicateur parmi d’autres.","effects":{"budget":2,"popularite":-2},"news":"Le Premier ministre : le temps d’attente est « un indicateur parmi d’autres »"},{"tone":"offensive","label":"Pendant que les provinces cherchent des coupables, mon gouvernement cherche des solutions. Nous ouvrirons des cliniques, avec ou sans leur bénédiction.","effects":{"popularite":5,"cohesion":-3,"budget":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les juristes consultent la Constitution, au ralenti"}],"news":"Le Premier ministre menace d’ouvrir des cliniques fédérales"}]},{"id":"canada-q-epicerie-prix","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":42},"text":"Le prix du beurre, du café et des pommes de terre dépasse celui des livres de droit constitutionnel. Que dites-vous aux familles qui font leur épicerie au compte-gouttes ?","answers":[{"tone":"franche","label":"Que je les entends, et que je ne peux pas baisser les prix par décret. Je peux aider les ménages qui en ont besoin et surveiller les marges des grandes chaînes.","effects":{"pouvoirAchat":4,"budget":-3,"economie":-2},"delayed":[{"delay":2,"effects":{"pouvoirAchat":2},"label":"Un code de conduite volontaire fait le tour des rayons"}],"news":"Épicerie : le Premier ministre promet de surveiller les marges"},{"tone":"langue-de-bois","label":"La hausse des prix est un phénomène mondial, et nous agissons de manière ciblée pour que les ménages vulnérables soient accompagnés, avec compassion.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Le Premier ministre invoque le « phénomène mondial » du beurre"},{"tone":"offensive","label":"Les grandes chaînes d’alimentation font des profits de vacances aux Bahamas pendant que les familles comptent les œufs. Cela finit maintenant.","effects":{"pouvoirAchat":5,"economie":-4,"international":-2},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Les chaînes menacent de fermer des magasins"}],"news":"Le Premier ministre déclare la guerre aux profits des épiceries"}]},{"id":"canada-q-loyers-villes","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":52},"text":"À Toronto, à Vancouver et à Montréal, on loue des placards avec vue sur la grue pour le prix d’un manoir. Allez-vous construire des logements ou juste des conférences de presse sur le sujet ?","answers":[{"tone":"franche","label":"Il faut construire, vite et en grand nombre, et cela exige de convaincre les municipalités de dire oui. Je veux des permis en jours, pas en années.","effects":{"pouvoirAchat":4,"budget":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les premières grues changent de quartier"}],"news":"Logement : le Premier ministre veut « des permis en jours, pas en années »"},{"tone":"langue-de-bois","label":"Le logement est un défi complexe qui interpelle tous les ordres de gouvernement. Une stratégie ambitieuse sera déposée dans un horizon raisonnable.","effects":{"pouvoirAchat":2,"popularite":-3},"news":"Logement : « un horizon raisonnable », promet le Premier ministre"},{"tone":"offensive","label":"Les spéculateurs et les villes qui bloquent les chantiers auront un choix simple : construire ou perdre leurs fonds fédéraux.","effects":{"pouvoirAchat":5,"popularite":2,"assemblee":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les maires répondent par une lettre de dix pages"}],"news":"Logement : le Premier ministre menace de couper les fonds aux villes"}]},{"id":"canada-q-securite-vols-auto","theme":"securite","condition":{"gauge":"securite","op":"<","value":55},"text":"Les vols de voitures explosent et certaines finissent dans des conteneurs au port. La sécurité fédérale, c’est un gros trousseau de clés perdu ?","answers":[{"tone":"franche","label":"Nous avons trop attendu. Je mets plus d’agents aux ports, plus d’échanges avec les polices locales, et des peines plus sévères pour les réseaux organisés.","effects":{"securite":5,"budget":-3,"popularite":-2},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Des conteneurs suspects sont enfin ouverts"}],"news":"Vols d’autos : le Premier ministre renforce la surveillance des ports"},{"tone":"langue-de-bois","label":"La lutte contre le crime organisé est une priorité, et nous travaillons avec nos partenaires pour une réponse concertée, coordonnée et harmonisée.","effects":{"securite":2,"popularite":-2},"news":"Vols d’autos : une réponse « concertée, coordonnée et harmonisée »"},{"tone":"offensive","label":"Les voleurs devraient savoir que nous ne sommes pas seulement polis. Nous allons les retrouver, eux et leurs conteneurs, jusqu’à l’autre bout de la planète.","effects":{"securite":5,"popularite":3,"international":-4,"budget":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Un pays étranger s’offusque d’être soupçonné"}],"news":"Le Premier ministre : « On ne fait pas que s’excuser »"}]},{"id":"canada-q-cohesion-quebec","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":45},"text":"Le Bloc des Intérêts du Québec parle de souveraineté comme d’un sujet de brunch, et l’Ouest accuse Ottawa de tout. Le pays tient-il encore ensemble avec du ruban adhésif ?","answers":[{"tone":"franche","label":"Ce pays tient par des compromis, et ils exigent de la patience. Je parlerai au Québec, à l’Ouest et à l’Atlantique avec la même sincérité.","effects":{"cohesion":5,"popularite":-2,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Une conférence des premiers ministres finit sans cris"}],"news":"Unité : le Premier ministre promet d’écouter toutes les régions"},{"tone":"langue-de-bois","label":"Notre fédération est une réussite diversifiée et résiliente, fondée sur le respect mutuel. Chaque région joue un rôle essentiel dans notre belle mosaïque.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre vante « notre belle mosaïque »"},{"tone":"offensive","label":"Ceux qui menacent de quitter le pays devraient d’abord expliquer qui paiera la facture. Le fédéralisme, c’est aussi apprendre à compter.","effects":{"popularite":4,"cohesion":-5,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-3},"label":"Le Bloc réplique avec un tableau encore plus long"}],"news":"Le Premier ministre : « Le fédéralisme, c’est aussi apprendre à compter »"}]},{"id":"canada-q-langues-affichage","theme":"cohesion","text":"Le bilinguisme officiel coûte cher en traducteurs, mais personne ne veut perdre ni un « bonjour » ni un « hello ». Faut-il revoir les langues officielles, ou simplement imprimer des étiquettes plus petites ?","answers":[{"tone":"franche","label":"Les deux langues officielles font partie de notre identité. Nous les protégerons, et nous veillerons à ce que le service soit vraiment disponible partout.","effects":{"cohesion":4,"budget":-3,"popularite":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les bureaux des régions engagent des réceptionnistes bilingues"}],"news":"Langues officielles : le Premier ministre promet un service réel, partout"},{"tone":"langue-de-bois","label":"Le bilinguisme est une valeur fondamentale, et il évolue. Un examen attentif, sans précipitation, sera mené dans les deux langues, en parallèle.","effects":{"cohesion":2,"international":-2},"news":"Le Premier ministre promet un examen « dans les deux langues, en parallèle »"},{"tone":"offensive","label":"Si l’on veut gaspiller moins, qu’on commence par supprimer les formulaires que personne ne lit, dans les deux langues. Les langues, elles, restent.","effects":{"popularite":4,"budget":3,"cohesion":-3,"assemblee":-2},"news":"Le Premier ministre propose de supprimer les formulaires inutiles"}]},{"id":"canada-q-carbone-ristourne","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":42},"text":"Vous taxez le carbone, mais les Canadiens ne voient que la taxe, jamais la ristourne. Le climat réchauffe la planète, et la taxe réchauffe les esprits. Comment faire mieux ?","answers":[{"tone":"franche","label":"En expliquant, en versant la ristourne plus visiblement et en ciblant les gros pollueurs. Le prix du carbone ne marche que si les gens voient l’argent revenir.","effects":{"ecologie":5,"popularite":-3,"budget":-2},"delayed":[{"delay":3,"effects":{"ecologie":2},"label":"Les ristournes sont remarquées par la population"}],"news":"Carbone : le Premier ministre veut une ristourne « enfin visible »"},{"tone":"langue-de-bois","label":"La tarification est un outil parmi d’autres dans notre trousse climatique, qui inclut des incitatifs, des innovations et des plans en développement.","effects":{"ecologie":2,"popularite":-2},"news":"Le Premier ministre ressort sa « trousse climatique »"},{"tone":"offensive","label":"La planète ne négocie pas avec ceux qui comptent les sous à la pompe. Nous maintenons la taxe, et nous le ferons avec le sourire.","effects":{"ecologie":5,"popularite":-4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Un convoi de camionnettes klaxonne devant la Chambre"}],"news":"Carbone : le Premier ministre maintient la taxe « avec le sourire »"}]},{"id":"canada-q-forets-climat-vert","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":62},"text":"Vos politiques vertes plaisent à la ville mais font frémir les régions qui vivent du pétrole, du gaz et du bois. Peut-on protéger les forêts sans fâcher ceux qui les exploitent ?","answers":[{"tone":"franche","label":"Pas entièrement. Je veux une transition équitable : des emplois verts avant les fermetures, jamais après. Les travailleurs ne sont pas les ennemis du climat.","effects":{"cohesion":4,"ecologie":-2,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Des usines de transformation ouvrent dans le Nord"}],"news":"Transition équitable : le Premier ministre promet des emplois avant les fermetures"},{"tone":"langue-de-bois","label":"La transition énergétique est un parcours, et nous avancerons d’un pas prudent, dans le respect de toutes les ressources et de tous les horizons.","effects":{"ecologie":2,"economie":-2},"news":"Le Premier ministre avance « d’un pas prudent » vers la transition"},{"tone":"offensive","label":"La forêt est un bien commun, pas la chasse gardée d’un conseil d’administration. Nous protégerons les arbres, et les lobbyistes devront changer de prairie.","effects":{"ecologie":5,"popularite":2,"economie":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les syndicats forestiers manifestent en camionnette"}],"news":"Le Premier ministre : « La forêt n’est pas la chasse gardée d’un conseil »"}]},{"id":"canada-q-voisin-sud","theme":"international","condition":{"gauge":"international","op":"<","value":45},"text":"Le voisin du sud vous oublie dans ses discours, vos alliés vous confondent avec votre voisin, et l’ONU vous demande de répéter. Où est passée l’influence canadienne ?","answers":[{"tone":"franche","label":"Nous avons été discrets trop longtemps. Je retourne dans les sommets, avec des idées claires, une diplomatie plus active et une meilleure carte de visite.","effects":{"international":5,"budget":-3,"popularite":-2},"delayed":[{"delay":3,"effects":{"international":2},"label":"Une conférence internationale se tient enfin ici"}],"news":"Le Premier ministre veut redonner de la voix au Canada"},{"tone":"langue-de-bois","label":"Le Canada demeure un partenaire fiable, respecté et recherché. Notre influence se mesure à la qualité de notre écoute, qui est exceptionnelle.","effects":{"international":2,"popularite":-2},"news":"Le Premier ministre mesure l’influence du Canada à « la qualité de son écoute »"},{"tone":"offensive","label":"Ceux qui nous confondent avec leur voisin finiront par s’excuser, eux aussi. En attendant, nous plantons le drapeau là où ça compte.","effects":{"popularite":4,"international":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Un ambassadeur est convoqué pour un café"}],"news":"Le Premier ministre : « Ils s’excuseront à leur tour »"}]},{"id":"canada-q-arctique-souverainete","theme":"international","text":"Le passage du Nord-Ouest fond, les navires étrangers s’y intéressent, et votre flotte de brise-glaces tient dans un seul garage. Qui protège l’Arctique, vous ou la neige ?","answers":[{"tone":"franche","label":"C’est une question de souveraineté, de climat et de communautés du Nord. J’investis dans les brise-glaces, les radars, et dans les collectivités qui y vivent.","effects":{"international":4,"securite":3,"budget":-5},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Un premier brise-glace sort du chantier"}],"news":"Arctique : le Premier ministre investit dans les brise-glaces"},{"tone":"langue-de-bois","label":"L’Arctique est une priorité stratégique qui exige une approche intégrée, durable et fondée sur la coopération avec nos alliés, et avec les phoques.","effects":{"international":2,"budget":-2},"news":"Arctique : le Premier ministre promet de coopérer « avec nos alliés et les phoques »"},{"tone":"offensive","label":"Le Nord est à nous, de la baie à l’océan. Qui y vient sans frapper doit s’attendre à croiser un patrouilleur et un thermos de café chaud.","effects":{"popularite":5,"securite":3,"international":-5},"delayed":[{"delay":2,"effects":{"international":-3},"label":"Des diplomates étrangers froncent les sourcils, au chaud"}],"news":"Arctique : « Le Nord est à nous », lance le Premier ministre"}]},{"id":"canada-q-minorite-defiance","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":35},"text":"Votre gouvernement est minoritaire, le Nouveau Parti du Peuple soupire et le Bloc compte les jours. Un vote de défiance se joue-t-il à chaque café du matin ?","answers":[{"tone":"franche","label":"Un gouvernement minoritaire doit négocier chaque fois, et c’est ce que le peuple a demandé. Je tends la main à tous les partis, même à ceux qui ne la serrent pas.","effects":{"assemblee":5,"popularite":-2,"budget":-3},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Le NPP accepte de négocier un budget"}],"news":"Minorité : le Premier ministre tend la main à tous les partis"},{"tone":"langue-de-bois","label":"Le gouvernement mène des consultations fructueuses avec l’ensemble des groupes parlementaires, dans un esprit de collaboration et de petits gâteaux.","effects":{"assemblee":2,"popularite":-2},"news":"Le Premier ministre mène des consultations « dans un esprit de petits gâteaux »"},{"tone":"offensive","label":"S’ils veulent des élections en plein hiver, qu’ils votent contre nous. Les Canadiens verront bien qui a laissé les bottes au vestiaire.","effects":{"popularite":5,"assemblee":-4,"cohesion":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les partis comptent leurs bottes"}],"news":"Le Premier ministre défie ses rivaux de provoquer des élections hivernales"}]},{"id":"canada-q-majorite-fonctions","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":60},"text":"Vous disposez d’une majorité confortable à la Chambre des communes. Les députés votent comme un seul homme. Est-ce de la discipline, de la peur, ou du café gratuit ?","answers":[{"tone":"franche","label":"De la discipline, parfois, et du débat, toujours à huis clos. Je préfère des élus qui disent non avant le vote plutôt qu’après les sondages.","effects":{"popularite":3,"assemblee":-3},"news":"Le Premier ministre : « Je préfère les élus qui disent non avant le vote »"},{"tone":"langue-de-bois","label":"Notre caucus est uni autour d’un projet commun. Le café est un détail logistique, mais il est excellent.","effects":{"assemblee":2,"popularite":-2},"news":"Le Premier ministre défend l’unité de son caucus et son café"},{"tone":"offensive","label":"Quand on a la majorité, on gouverne. Si l’opposition veut gouverner, qu’elle gagne des sièges, pas des débats à la radio.","effects":{"popularite":4,"assemblee":3,"cohesion":-4,"international":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"La motion de clôture revient sur la table"}],"news":"Le Premier ministre à l’opposition : « Gagnez des sièges, pas des débats »"}]},{"id":"canada-q-feux-ouest","theme":"crise","crisisId":"canada-feux-de-foret","text":"Le ciel est orange sur l’Ouest, des villages évacuent et les avions-citernes manquent. Ottawa regarde les flammes à la télévision, ou compte-t-il intervenir ?","answers":[{"tone":"franche","label":"Nous envoyons tout ce que nous avons, l’armée, les avions et les pompiers d’autres provinces, et nous remercions ceux qui sont déjà sur place. Le reste viendra après.","effects":{"popularite":4,"securite":3,"budget":-4},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les provinces s’entraident, pour une fois sans conférence"}],"news":"Feux de forêt : le Premier ministre déploie l’armée et les avions"},{"tone":"langue-de-bois","label":"La situation évolue rapidement, et nous coordonnons nos efforts avec les autorités provinciales dans un esprit de solidarité qui fait honneur à tout le monde.","effects":{"securite":2,"popularite":-2},"news":"Feux de forêt : « un esprit de solidarité », assure le Premier ministre"},{"tone":"offensive","label":"Pour une fois, personne ne peut dire que le climat est une opinion. Je veux un plan de prévention, des budgets et des coupe-feu, pas des condoléances.","effects":{"ecologie":4,"popularite":2,"economie":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"L’industrie pétrolière dénonce un réquisitoire"}],"news":"Feux : le Premier ministre exige « des coupe-feu, pas des condoléances »"}]},{"id":"canada-q-verglas-reseau","theme":"crise","crisisId":"canada-hiver-tempete-verglas","text":"Une tempête de verglas a coupé le courant à des millions de foyers, et les enfants jouent aux cartes à la chandelle depuis quatre jours. Où est le gouvernement fédéral, avec ses grandes promesses d’infrastructure ?","answers":[{"tone":"franche","label":"Nous aidons les provinces à rétablir le courant, avec des équipes, des génératrices et des abris chauffés. Et nous enquêterons sur la solidité du réseau électrique.","effects":{"popularite":4,"securite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Le réseau électrique reçoit enfin des fonds de remise à niveau"}],"news":"Verglas : le Premier ministre envoie génératrices et équipes"},{"tone":"langue-de-bois","label":"Les équipes sont mobilisées et la situation est suivie de près. Nous invitons la population à garder son calme, ses couvertures et son sens de l’humour.","effects":{"popularite":2,"securite":-2},"news":"Verglas : le Premier ministre recommande « couvertures et humour »"},{"tone":"offensive","label":"Ceux qui ont retardé l’entretien du réseau pendant dix ans portent une lourde responsabilité. On commence par les noms, ensuite par les câbles.","effects":{"popularite":5,"securite":2,"cohesion":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les compagnies d’électricité contre-attaquent en justice"}],"news":"Verglas : le Premier ministre pointe « ceux qui ont retardé l’entretien »"}]},{"id":"canada-q-pont-blocage","theme":"crise","crisisId":"canada-blocage-pont-frontalier","text":"Un convoi de camions bloque un pont frontalier, les usines d’automobiles manquent de pièces et les klaxons s’entendent jusque dans la capitale. Négociez-vous, ou envoyez-vous les remorqueuses ?","answers":[{"tone":"franche","label":"Le droit de manifester est sacré, le droit de bloquer un pont ne l’est pas. Je parle aux organisateurs, et la police dégagera la voie si le dialogue échoue.","effects":{"securite":4,"economie":3,"popularite":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les manifestants se disent trahis par la poignée de main"}],"news":"Pont bloqué : le Premier ministre offre le dialogue, puis l’ultimatum"},{"tone":"langue-de-bois","label":"Nous suivons la situation et nous invitons toutes les parties à la retenue. Les automobilistes sont priés de se tourner vers des routes alternatives.","effects":{"securite":2,"economie":-3},"news":"Pont bloqué : le Premier ministre suggère des routes alternatives"},{"tone":"offensive","label":"On ne prend pas l’économie en otage avec un klaxon. Je veux que les remorqueuses aient fini avant le déjeuner, et qu’on ne parle plus de ça.","effects":{"economie":5,"securite":3,"cohesion":-4,"popularite":-2},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Les images de remorquage font le tour de la planète"}],"news":"Pont bloqué : « Les remorqueuses avant le déjeuner », ordonne le Premier ministre"}]},{"id":"canada-q-referendum-souverainiste","theme":"crise","crisisId":"canada-referendum-souverainiste","text":"Un parti souverainiste évoque un nouveau référendum, et les marchés tremblent. Comment répondre à ceux qui veulent partir sans humilier ceux qui veulent rester ?","answers":[{"tone":"franche","label":"Avec respect et avec clarté. Le dialogue est ouvert, la question doit être claire, et chaque Canadien aura droit à une réponse honnête sur ce que coûterait un départ.","effects":{"cohesion":4,"popularite":2,"economie":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Le débat se déplace des slogans vers les chiffres"}],"news":"Référendum : le Premier ministre exige une question claire"},{"tone":"langue-de-bois","label":"L’unité canadienne est une valeur partagée par une majorité, et nous poursuivons le dialogue avec toutes les régions dans un esprit d’ouverture respectueuse.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre invoque « une ouverture respectueuse »"},{"tone":"offensive","label":"On ne rompt pas un pays comme on annule un abonnement. J’invite les souverainistes à mettre leurs chiffres sur la table, ensuite leurs drapeaux.","effects":{"popularite":4,"international":2,"cohesion":-5},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Le Bloc dénonce une comparaison méprisante"}],"news":"Le Premier ministre : « On ne rompt pas un pays comme un abonnement »"}]},{"id":"canada-q-epicerie-nord-penurie","theme":"crise","crisisId":"canada-epicerie-nord","text":"Dans le Grand Nord, un litre de lait coûte autant qu’un billet d’avion, et les magasins sont vides depuis le dernier avion. Que faites-vous pour les communautés isolées ?","answers":[{"tone":"franche","label":"J’augmente les subventions au transport des aliments, et je veux que les communautés choisissent ce qu’elles reçoivent. Leurs besoins ne se décident pas à Ottawa.","effects":{"cohesion":4,"pouvoirAchat":3,"budget":-5},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les étagères du Nord se remplissent, un peu"}],"news":"Nord : le Premier ministre augmente les subventions aux aliments"},{"tone":"langue-de-bois","label":"La sécurité alimentaire dans le Nord est un enjeu majeur, et le gouvernement poursuit sa réflexion en partenariat avec les communautés, avec les compagnies aériennes et avec l’hiver.","effects":{"cohesion":2,"popularite":-2},"news":"Nord : le Premier ministre poursuit sa réflexion, avec l’hiver"},{"tone":"offensive","label":"Nous allons obliger les grands distributeurs à justifier leurs prix dans le Nord. Quiconque vend une pomme au prix d’un voyage devra expliquer le voyage.","effects":{"pouvoirAchat":5,"popularite":2,"economie":-4,"international":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les distributeurs menacent de réduire leurs vols"}],"news":"Nord : le Premier ministre exige que les distributeurs justifient leurs prix"}]},{"id":"canada-q-crise-generique-bottes","theme":"crise","text":"En pleine crise, la population se demande si le gouvernement a un plan ou simplement des bottes. Vous parlez de coordination, mais qui tient le volant ?","answers":[{"tone":"franche","label":"Moi. Je m’en tiens responsable, je publierai le calendrier des décisions et je reconnaîtrai les erreurs au fur et à mesure, pas dans un rapport dans trois ans.","effects":{"popularite":5,"assemblee":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les provinces apprécient la transparence, du bout des lèvres"}],"news":"Le Premier ministre : « Je tiens le volant et je publie le calendrier »"},{"tone":"langue-de-bois","label":"Une équipe de coordination est à l’œuvre, avec des comités et des sous-comités, et ces comités ont chacun un plan, ou presque.","effects":{"securite":2,"popularite":-3},"news":"Crise : le Premier ministre brandit ses comités et sous-comités"},{"tone":"offensive","label":"Je n’ai pas de leçons à recevoir de gens qui regardent la crise depuis la touche. Le moment est à l’action, pas aux éditoriaux.","effects":{"popularite":4,"securite":2,"international":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les éditorialistes sortent leurs plumes"}],"news":"Crise : le Premier ministre renvoie les critiques à la touche"}]},{"id":"canada-q-scandale-jet-chalet","theme":"scandale","text":"On apprend que votre ministre des Finances est parti en week-end à un chalet appartenant à une firme de consultants. Il jure avoir payé son thé. Quel est le prix d’un chalet dans le cadre d’un week-end sans éthique ?","answers":[{"tone":"franche","label":"Je demande un rapport du commissaire à l’éthique, et si une règle a été violée, il y aura des conséquences. Personne n’est au-dessus des lois ni au-dessus d’un chalet.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Le rapport conclut à une erreur de jugement, pas de malice"}],"news":"Chalet : le Premier ministre demande une enquête sur son ministre"},{"tone":"langue-de-bois","label":"Le ministre a respecté l’esprit des règles, et ce week-end familial s’est déroulé dans la plus grande transparence, à l’exception du chalet.","effects":{"assemblee":2,"popularite":-4},"news":"Chalet : « le plus grand esprit de transparence », selon le Premier ministre"},{"tone":"offensive","label":"Les chalets de l’opposition ont reçu autant d’invités que celui-là. Voilà une affaire montée en épingle par des gens qui n’ont jamais de week-end gratuit.","effects":{"popularite":3,"assemblee":-4,"cohesion":-3},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les photos d’un autre chalet fuitent"}],"news":"Chalet : le Premier ministre accuse l’opposition d’avoir des invités aussi"}]},{"id":"canada-q-scandale-deneigement","theme":"scandale","text":"Un contrat de déneigement fédéral, attribué à l’entreprise du beau-frère d’un conseiller, a coûté trois fois le prix de la neige. Faut-il y voir un conflit d’intérêts ou une grande tradition familiale ?","answers":[{"tone":"franche","label":"Le contrat a été attribué sans appel d’offres sérieux, c’est inacceptable. Il sera annulé, et le conseiller sera suspendu en attendant l’enquête.","effects":{"popularite":4,"budget":2,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les conseillers se demandent qui sera le suivant"}],"news":"Déneigement : le Premier ministre annule le contrat et suspend son conseiller"},{"tone":"langue-de-bois","label":"Le contrat a été attribué conformément aux processus, qui sont en cours d’examen, par un comité qui examinera comment les processus pourront être examinés.","effects":{"budget":2,"popularite":-4},"news":"Déneigement : un comité examinera comment examiner le contrat"},{"tone":"offensive","label":"La neige est tombée, elle a été retirée, le travail a été fait. Le reste, c’est de l’hiver politique.","effects":{"popularite":3,"securite":2,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Un journal publie le contrat, page par page"}],"news":"Déneigement : « le reste, c’est de l’hiver politique », répond le Premier ministre"}]},{"id":"canada-q-scandale-note-fuite","theme":"scandale","text":"Une note confidentielle sur l’assurance médicaments a été fuitée à la presse, avec vos annotations en marge : « à reporter après les élections ». Comment expliquer l’écriture de votre main ?","answers":[{"tone":"franche","label":"C’est mon écriture, et mon erreur. J’ai voulu protéger le calendrier, pas le projet. Je me suis mal exprimé, et je m’en excuse. Nous irons de l’avant.","effects":{"popularite":4,"assemblee":-2,"cohesion":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les provinces s’empressent de lui proposer un calendrier"}],"news":"Note fuitée : le Premier ministre reconnaît son écriture et ses excuses"},{"tone":"langue-de-bois","label":"Des documents de travail contiennent souvent des notes préliminaires qui ne reflètent pas des positions arrêtées. Le gouvernement reste engagé envers les Canadiens.","effects":{"assemblee":2,"popularite":-3},"news":"Note fuitée : « des notes préliminaires », plaide le Premier ministre"},{"tone":"offensive","label":"Cherchez plutôt qui a fuité cette note. On a des fuites aussi nombreuses qu’au printemps sur le toit de l’édifice, et personne ne les répare.","effects":{"popularite":3,"securite":2,"assemblee":-4,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"La source fuitée révèle un autre dossier"}],"news":"Note fuitée : le Premier ministre cherche la source plutôt que le reproche"}]},{"id":"canada-q-culture-hockey","theme":"popularite","text":"La finale de hockey tombe le soir de votre vote de confiance. Les députés menacent de voter en regardant le match. Votre priorité : la nation ou le deuxième tiers ?","answers":[{"tone":"franche","label":"Les deux, dans cet ordre, mais je vais prier pour une prolongation. Un bon gouvernement sait vivre avec un calendrier de hockey.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les députés votent entre deux tiers-temps, de bonne humeur"}],"news":"Le Premier ministre jure d’aimer à la fois le vote et le hockey"},{"tone":"langue-de-bois","label":"Le sport rassemble les Canadiens, et le travail parlementaire demeure essentiel. Nous trouverons un équilibre entre l’un et l’autre, dans le respect des deux.","effects":{"popularite":2,"cohesion":-2},"news":"Le Premier ministre cherche un équilibre entre vote et hockey"},{"tone":"offensive","label":"Un vote qui commence pendant le match, c’est une insulte au sport national. Je déplace la séance, et on se retrouve à la patinoire pour le débat.","effects":{"popularite":5,"assemblee":-3,"budget":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"La présidence rappelle que la Chambre n’a pas de glace"}],"news":"Le Premier ministre déplace le vote pour ne pas manquer le match"}]},{"id":"canada-q-culture-beignes","theme":"cohesion","text":"On raconte que les grandes décisions se prennent au comptoir de beignes avec un café double-double. Est-ce vrai, et le café est-il fédéral ?","answers":[{"tone":"franche","label":"Bien sûr que oui. C’est là qu’on entend les gens, loin des micros et des conseillers. Je paie toujours ma tournée, avec mon salaire, pas avec le budget.","effects":{"popularite":4,"cohesion":2,"economie":-2},"news":"Le Premier ministre avoue : « Les décisions se prennent au comptoir »"},{"tone":"langue-de-bois","label":"Notre tradition de rencontrer la population dans des lieux accessibles est profondément enracinée, et le café y est tout à fait conforme à nos valeurs.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre garantit que le café est conforme aux valeurs du pays"},{"tone":"offensive","label":"Un pays qui n’a pas de beignes dans ses réunions n’en a pas non plus dans ses idées. J’en ferai livrer à tous les partis, même au Bloc.","effects":{"popularite":5,"cohesion":-3,"budget":-2},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Le Bloc salue les beignes mais pas le geste"}],"news":"Le Premier ministre fait livrer des beignes à tous les partis"}]},{"id":"canada-q-culture-meteo-hiver","theme":"popularite","text":"Il fait moins trente-huit dehors et la Chambre est à moitié vide parce que les députés ont perdu leur voiture sous un banc de neige. Gouverner un pays aussi froid, est-ce de la politique ou de la survie ?","answers":[{"tone":"franche","label":"Les deux, et c’est ce qui nous rend solidaires. J’ai déjà poussé la voiture d’un voisin, et ça m’a appris plus que bien des briefings.","effects":{"popularite":5,"budget":-2},"news":"Le Premier ministre : « J’ai appris plus en poussant une voiture »"},{"tone":"langue-de-bois","label":"Le froid est une réalité saisonnière que notre pays a toujours surmontée, grâce à la résilience de sa population et à la qualité de ses manteaux.","effects":{"popularite":2,"economie":-2},"news":"Le Premier ministre vante « la qualité de nos manteaux »"},{"tone":"offensive","label":"Je suggère aux députés qui arrivent en retard de ne pas blâmer la neige, mais l’horloge. Le blizzard ne vote pas, et il n’est pas excusé non plus.","effects":{"popularite":3,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les députés répondent avec un sac de sel"}],"news":"Le Premier ministre rappelle que le blizzard ne vote pas"}]},{"id":"canada-q-culture-excuses","theme":"international","text":"On dit que votre diplomatie s’excuse plus souvent qu’elle n’annonce. Un diplomate canadien peut-il dire non sans commencer par « désolé » ?","answers":[{"tone":"franche","label":"Oui, mais le non est plus fort quand il est poli. Un « non, désolé » de notre part vaut dix refus ailleurs, et personne n’est vexé.","effects":{"international":4,"popularite":-2},"news":"Diplomatie : « un non, désolé, vaut dix refus », dit le Premier ministre"},{"tone":"langue-de-bois","label":"Notre approche privilégie le dialogue, la compréhension et l’écoute respectueuse, et nous nous excusons d’avance pour tout malentendu qui pourrait survenir.","effects":{"international":2,"popularite":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Un partenaire demande si c’est vraiment un oui"}],"news":"Le Premier ministre s’excuse d’avance pour toute la diplomatie"},{"tone":"offensive","label":"La prochaine fois qu’un pays nous marche sur le pied, c’est lui qui s’excusera. Nous avons de la mémoire, et un carnet très bien tenu.","effects":{"popularite":5,"international":-5},"delayed":[{"delay":3,"effects":{"international":-2},"label":"Un ambassadeur propose d’ouvrir un dialogue sur le carnet"}],"news":"Le Premier ministre promet que le carnet de rancunes est bien tenu"}]},{"id":"canada-q-culture-erable","theme":"international","text":"Le sirop d’érable est devenu un enjeu stratégique, avec des réserves, des stocks et même des cambriolages. Faut-il une politique nationale du sirop, ou laisse-t-on couler ?","answers":[{"tone":"franche","label":"Le sirop est une fierté nationale et une industrie vitale. Je protège les producteurs, les réserves et les érablières. Les voleurs de sirop seront traités sans douceur.","effects":{"popularite":4,"economie":2,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les exportations de sirop fondent sur les marchés"}],"news":"Sirop d’érable : le Premier ministre protège les érablières"},{"tone":"langue-de-bois","label":"Le sirop est un produit de qualité, d’origine locale et de saison, et nous entendons soutenir ce secteur avec la douceur qui lui convient.","effects":{"economie":2,"popularite":-2},"news":"Le Premier ministre soutiendra le sirop « avec douceur »"},{"tone":"offensive","label":"Le sirop d’érable est notre or liquide. Qui y touche touche au pays. J’invite nos partenaires commerciaux à payer le prix ou à se passer de crêpes.","effects":{"popularite":5,"economie":3,"international":-5},"delayed":[{"delay":2,"effects":{"international":-3},"label":"Des partenaires trouvent le sirop d’une autre région"}],"news":"Le Premier ministre : « Le sirop est notre or liquide »"}]},{"id":"canada-q-culture-capitale-canal","theme":"popularite","text":"Chaque hiver, la capitale transforme un canal en patinoire de plusieurs kilomètres, et la patinoire attire plus de gens que votre discours. Qui gouverne vraiment la ville, vous ou la glace ?","answers":[{"tone":"franche","label":"La glace, sans hésiter. Elle ne se plaint pas, ne ment pas et fond sans faire de scandale. J’apprends d’elle, mais je passe moins bien sur patins.","effects":{"popularite":5,"assemblee":-2},"news":"Le Premier ministre : « Ottawa est gouvernée par la glace »"},{"tone":"langue-de-bois","label":"La patinoire est un lieu de rassemblement important qui témoigne de la vitalité de notre capitale et de la glace de qualité qu’elle accueille chaque année.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre salue « la qualité de la glace » du canal"},{"tone":"offensive","label":"Si les gens préfèrent patiner à m’écouter, c’est qu’ils ont raison de se méfier des longs discours. Je promets d’être plus court que le canal.","effects":{"popularite":4,"international":-2,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"L’opposition mesure la longueur des discours au mètre"}],"news":"Le Premier ministre promet des discours plus courts que le canal"}]},{"id":"canada-q-culture-federalisme-fete","theme":"cohesion","text":"Pour la fête nationale, chaque province veut son propre feu d’artifice, sa propre chanson, et son propre horaire. Est-ce du fédéralisme coopératif ou un concours de logistique ?","answers":[{"tone":"franche","label":"C’est notre force et notre migraine. Je vais réunir les provinces autour d’un même soir, avec des feux d’artifice pour toutes, et un café pour les organisateurs.","effects":{"cohesion":4,"budget":-3,"popularite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les familles saluent un feu d’artifice partagé"}],"news":"Fête nationale : le Premier ministre unit les provinces autour d’un soir"},{"tone":"langue-de-bois","label":"La diversité de nos célébrations est une richesse. Chaque région est libre de s’exprimer, pourvu que l’ensemble reste harmonieux et ponctuel.","effects":{"cohesion":2,"international":-2},"news":"Fête nationale : « harmonieux et ponctuel », exige le Premier ministre"},{"tone":"offensive","label":"Que chaque province fasse son feu d’artifice, à ses frais. Si Ottawa doit payer pour tous, nous le ferons à notre heure, avec nos fusées.","effects":{"budget":3,"popularite":2,"cohesion":-4},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Un premier ministre provincial parle de feux de joie"}],"news":"Fête nationale : le Premier ministre laisse la facture des feux aux provinces"}]}]}'),u={pays:e,version:1,textes:s,institutions:a,election:n,lois:t,crises:i,missions:r,presse:o};export{i as crises,u as default,n as election,a as institutions,t as lois,r as missions,e as pays,o as presse,s as textes,l as version};
